   for(const [s,l] of [[2.6,'léger'],[3,'modéré'],[4,'sévère']]){const a=P(s,0),b=P(s,150);x.strokeStyle='#d11';x.setLineDash([4,3]);x.beginPath();x.moveTo(...a);x.lineTo(...b);x.stroke();x.setLineDash([]);x.fillStyle='#d11';x.fillText(l,a[0]+3,b[1]+12);}
